[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$CachePolicyPath,[string]$RouteId='data/dashboard',[string]$OutputPath='ES/Output/WebPageStudio/dynamic-state-replay.json')
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$policy=(Resolve-Path $CachePolicyPath).Path;if(-not $policy.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'CachePolicyPath must remain under project root.'};$p=Get-Content $policy -Raw -Encoding UTF8|ConvertFrom-Json;$route=@($p.routes|Where-Object routeId -eq $RouteId)|Select-Object -First 1;if(-not $route){throw "Route not found: $RouteId"}
$events=@([ordered]@{sequence=0;state='idle';cache='miss';action='request';detail='No cache entry; request would enter loading.'},[ordered]@{sequence=1;state='loading';cache='miss';action='render';detail='Render stable loading shell.'},[ordered]@{sequence=2;state='success';cache='revalidated';action='render';detail='Fresh response stored under etag-version key.'},[ordered]@{sequence=3;state='success';cache='hit';action='request';detail='Fresh cache hit avoids origin work.'},[ordered]@{sequence=4;state='loading';cache='stale';action='revalidate';detail='stale-while-revalidate serves stale while refresh is attempted.'},[ordered]@{sequence=5;state='success';cache='serve-stale';action='fallback';detail='Origin failure preserves last-known-good content.'},[ordered]@{sequence=6;state='empty';cache='bypass';action='render';detail='Empty payload is explicit and recoverable.'},[ordered]@{sequence=7;state='error';cache='bypass';action='retry';detail='Error state exposes retry without losing navigation context.'})
$o=[ordered]@{schemaVersion=1;recordType='WebPageStudioDynamicStateReplay';replayId=('dynamic-replay-'+[guid]::NewGuid().ToString('N').Substring(0,12));routeId=$RouteId;cachePolicyId=[string]$p.policyId;events=$events;finalState='error';runtimeStatus='runtime-not-run';nonClaims=@('No network request or backend process was executed','Replay proves state-machine determinism, not origin availability or CDN coherence')};$out=Join-Path $root $OutputPath;New-Item -ItemType Directory (Split-Path $out) -Force|Out-Null;[IO.File]::WriteAllText($out,($o|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));$o|ConvertTo-Json -Depth 10
